use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Charge {
    pub open: u64,
    pub append: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action { Open, Append }

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Withdrawal {
    pub id: u64,
    pub recipient: String,
    pub amount: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LedgerError {
    Unauthorized,
    InvalidInput,
    Paused,
    Overflow,
    InsufficientBalance,
    WithdrawalPending,
    NoMatchingWithdrawal,
}

pub struct ServiceLedger {
    owner: String,
    metadata: Option<(String, String)>,
    default_charge: Charge,
    user_charges: HashMap<String, Charge>,
    paused: bool,
    balance: u64,
    pending: Option<Withdrawal>,
    next_id: u64,
}

impl ServiceLedger {
    pub fn new(owner: String, default_charge: Charge) -> Result<Self, LedgerError> {
        if owner.is_empty() { return Err(LedgerError::InvalidInput); }
        Ok(Self { owner, metadata: None, default_charge, user_charges: HashMap::new(), paused: false, balance: 0, pending: None, next_id: 1 })
    }

    fn owner(&self, caller: &str) -> Result<(), LedgerError> {
        if caller == self.owner { Ok(()) } else { Err(LedgerError::Unauthorized) }
    }

    pub fn set_metadata(&mut self, caller: &str, specification: String, source: String) -> Result<(), LedgerError> {
        self.owner(caller)?;
        if specification.is_empty() || source.is_empty() { return Err(LedgerError::InvalidInput); }
        self.metadata = Some((specification, source));
        Ok(())
    }

    pub fn set_default_charge(&mut self, caller: &str, charge: Charge) -> Result<(), LedgerError> {
        self.owner(caller)?;
        self.default_charge = charge;
        Ok(())
    }

    pub fn set_user_charge(&mut self, caller: &str, user: String, charge: Charge) -> Result<(), LedgerError> {
        self.owner(caller)?;
        if user.is_empty() { return Err(LedgerError::InvalidInput); }
        self.user_charges.insert(user, charge);
        Ok(())
    }

    pub fn pause(&mut self, caller: &str) -> Result<(), LedgerError> {
        self.owner(caller)?;
        self.paused = true;
        Ok(())
    }

    pub fn resume(&mut self, caller: &str) -> Result<(), LedgerError> {
        self.owner(caller)?;
        self.paused = false;
        Ok(())
    }

    pub fn record(&mut self, user: &str, action: Action) -> Result<u64, LedgerError> {
        if user.is_empty() { return Err(LedgerError::InvalidInput); }
        if self.paused { return Err(LedgerError::Paused); }
        let charge = self.user_charges.get(user).copied().unwrap_or(self.default_charge);
        let amount = match action { Action::Open => charge.open, Action::Append => charge.append };
        let updated = self.balance.checked_add(amount).ok_or(LedgerError::Overflow)?;
        self.balance = updated;
        Ok(updated)
    }

    pub fn begin_withdrawal(&mut self, caller: &str, recipient: String, amount: u64) -> Result<Withdrawal, LedgerError> {
        self.owner(caller)?;
        if recipient.is_empty() || amount == 0 { return Err(LedgerError::InvalidInput); }
        if self.pending.is_some() { return Err(LedgerError::WithdrawalPending); }
        if amount > self.balance { return Err(LedgerError::InsufficientBalance); }
        let next = self.next_id.checked_add(1).ok_or(LedgerError::Overflow)?;
        let withdrawal = Withdrawal { id: self.next_id, recipient, amount };
        self.balance -= amount;
        self.next_id = next;
        self.pending = Some(withdrawal.clone());
        Ok(withdrawal)
    }

    pub fn finish_withdrawal(&mut self, caller: &str, id: u64, succeeded: bool) -> Result<(), LedgerError> {
        self.owner(caller)?;
        let pending = self.pending.as_ref().ok_or(LedgerError::NoMatchingWithdrawal)?;
        if pending.id != id { return Err(LedgerError::NoMatchingWithdrawal); }
        let amount = pending.amount;
        if !succeeded {
            self.balance = self.balance.checked_add(amount).ok_or(LedgerError::Overflow)?;
        }
        self.pending = None;
        Ok(())
    }

    pub fn balance(&self) -> u64 { self.balance }
    pub fn is_paused(&self) -> bool { self.paused }
}
